"""Insert or replace the auto-generated results section of the README between markers."""
import os, re, sys
REPO = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
START, END = "<!-- sa-results:start -->", "<!-- sa-results:end -->"
SOURCES = [("results/sa_eval/summary_vs_baselines.md", "Source-aware checkpoint (10k steps) against the baselines"),
           ("results/sa_ablation/summary.md", "Ablation of each part"),
           ("results/sa_eval_20k/summary_vs_baselines.md", "After 20k steps (stage 4b)")]
parts, files = [], []
for f, title in SOURCES:
    p = os.path.join(REPO, f)
    if not os.path.exists(p):
        continue
    body = re.sub(r"^# .*\n", "", open(p).read(), count=1)  # drop the file's H1
    body = re.sub(r"^#{2,3} ", lambda m: "#" + m.group(0), body, flags=re.M)  # demote headings one level
    parts.append(f"### {title}\n\n{body.strip()}\n"); files.append(f"`{f}`")
if not parts:
    sys.exit(0)
section = (f"{START}\n\n## Source-aware TabICL-M: results\n\n*Auto-generated by the training pipeline "
           f"(`checkpoints/tabicl-m-sa/pipeline.sh`). Full tables: {', '.join(files)}; training logs under "
           f"`checkpoints/tabicl-m-sa/`.*\n\n" + "\n".join(parts) + f"\n{END}")
readme = open(os.path.join(REPO, "README.md")).read()
if START in readme:
    readme = readme[: readme.index(START)] + section + readme[readme.index(END) + len(END):]
else:
    anchor = "## What remains"
    readme = readme.replace(anchor, section + "\n\n" + anchor, 1) if anchor in readme else readme + "\n\n" + section + "\n"
open(os.path.join(REPO, "README.md"), "w").write(readme); print("README section written")
